    /**
     * Tests getting all EmailMessages.
     *
     * @return    Collection
     */
    public List<EmailMessage> testGetAll() throws Throwable {
    LOGGER.info( "EmailMessageTest:testGetAll() - Retrieving Collection of EmailMessages:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all EmailMessage : " );
    List<EmailMessage> collection  = null;

    try {
        // call the static get method on the EmailMessageService
        collection = service.getAllEmailMessage();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            EmailMessage currEntity  = null;
            Iterator<EmailMessage> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getEmailMessageId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

